create extension if not exists pgcrypto;
create table if not exists public.resume_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,primary_positioning text,job_titles text[] default '{}',seniority text,years_experience text,job_families text[] default '{}',skills text[] default '{}',industries_domains text[] default '{}',education_certifications text[] default '{}',achievements_projects text[] default '{}',keywords text[] default '{}',evidence text[] default '{}',file_path text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,name));
create table if not exists public.jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,company text,job_title text,job_id text,job_url text not null,location text,application_url text,keywords text[] default '{}',required_skills text[] default '{}',preferred_skills text[] default '{}',experience_required text,match_score numeric,recommended_resume text,classification text,status text not null default 'Saved',discovered_at timestamptz not null default now(),date_applied timestamptz,recruiter_referral text,notes text,follow_up_date timestamptz,dedupe_key text not null,unique(user_id,dedupe_key));
alter table public.resume_profiles enable row level security;alter table public.jobs enable row level security;
create policy "own resume profiles" on public.resume_profiles for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own jobs" on public.jobs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public) values('resumes','resumes',false) on conflict(id) do nothing;
create policy "own resume files" on storage.objects for all using(bucket_id='resumes' and auth.uid()::text=(storage.foldername(name))[1]) with check(bucket_id='resumes' and auth.uid()::text=(storage.foldername(name))[1]);
